---
name: signals-dashboard
description: >-
  Use when creating or refreshing the AI/SI Industry Signals dashboard Page
  after a briefing run.
---
Use this to create or refresh the signals dashboard Page from a briefing run. The Page is a snapshot that changes only when a briefing, alert, or recap runs; never describe it as real-time or live. Load the canvas skill first. On the first run, create the Page with WriteCanvas (title "AI/SI Industry Signals") using the module below with the data block filled in, save its canvas_id and url to memory, and reuse them on every later run. On later runs, ReadCanvas, then EditCanvas only the block between `// ==== EDITION DATA` and `// ==== END EDITION DATA ====`, keeping the layout untouched and appending a row to EDITIONS. Only write the Page once there is real data; never publish it with the empty placeholders.

Fill the data only from real posts found this run; never invent posts, numbers, quotes, or links. Each Topic needs: id, priority (P1/P2/P3), topic, theme, voices (handles without @), count (distinct watchlist voices), likes (summed likes of its linked posts), quote (verbatim text of one linked post, trimmed to about 240 characters, with cite), summary (2-3 sentences), sides (two arrays of points when it is a debate, else null), links (2-4 posts, built with X(user, statusId)). EDITION has asOf, window, topLine, covered, total, postsRead. WORTH_READING is one Link; NEW_VOICES is up to two {handle, why, links}.

Module:

```tsx
import { Page, Section, Text, Callout, Table, Segmented, Select, Bars, LinkCards, ProsCons, Grid, TableOfContents, Scatter, AvatarStack, Status, Quote, Properties, Metrics, Rows, useState, useMemo } from "grok/canvas";

type Link = { title: string; site: string; date: string; href: string };
type Priority = "P1" | "P2" | "P3";
type Topic = { id: string; priority: Priority; topic: string; theme: string; voices: string[]; count: number; likes: number; quote: { text: string; cite: string }; summary: string; sides: string[][] | null; links: Link[] };

// ==== EDITION DATA: each run replaces EDITION, TOPICS, WORTH_READING, NEW_VOICES, and appends to EDITIONS ====
const EDITION = { asOf: "", window: "", topLine: "", covered: 0, total: 0, postsRead: 0 };
const X = (u: string, id: string) => `https://x.com/${u}/status/${id}`;
const TOPICS: Topic[] = [];
const WORTH_READING: Link = { title: "", site: "", date: "", href: "" };
const NEW_VOICES: { handle: string; why: string; links: Link[] }[] = [];
const EDITIONS: { date: string; topLine: string }[] = [];
// ==== END EDITION DATA ====

// ==== LAYOUT (no data below this line) ====
const PRIO_TONE: Record<Priority, "danger" | "warning" | "neutral"> = { P1: "danger", P2: "warning", P3: "neutral" };
const people = (vs: string[]) => vs.map((v: string) => ({ name: "@" + v }));
const fmtK = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n));

export default function App() {
  const [prio, setPrio] = useState<string>("All");
  const [theme, setTheme] = useState<string>("All");
  const [pick, setPick] = useState<string>(TOPICS[0]?.id ?? "");
  const themes = useMemo(() => ["All", ...Array.from(new Set(TOPICS.map((t: Topic) => t.theme)))], []);
  const shown = TOPICS.filter((t: Topic) => (prio === "All" || t.priority === prio) && (theme === "All" || t.theme === theme));
  const p1 = TOPICS.filter((t: Topic) => t.priority === "P1").slice(0, 3);
  const byTheme = useMemo(() => {
    const m = new Map<string, Set<string>>();
    TOPICS.forEach((t: Topic) => { const s = m.get(t.theme) ?? new Set<string>(); t.voices.forEach((v: string) => s.add(v)); m.set(t.theme, s); });
    return Array.from(m.entries()).map(([label, s]) => ({ label, value: s.size, display: `${s.size} voices` })).sort((a, b) => b.value - a.value);
  }, []);
  const count = (p: string) => TOPICS.filter((t: Topic) => p === "All" || t.priority === p).length;
  const sel = TOPICS.find((t: Topic) => t.id === pick) ?? TOPICS[0];
  const toc = [
    { label: "Headlines", id: "headlines" }, { label: "Priority map", id: "map" }, { label: "Ranked topics", id: "ranked" },
    { label: "Topic detail", id: "detail" }, { label: "Reading and new voices", id: "reading" }, { label: "Coverage", id: "coverage" }, { label: "Edition history", id: "history" },
  ];
  return (
    <Page title="AI/SI Industry Signals" width="wide" summary={`Edition of ${EDITION.asOf} · ranked from the X watchlist.`}>
      <Callout lead="Top line" tone="info">{EDITION.topLine}</Callout>
      <Metrics metrics={[
        { value: String(TOPICS.length), label: "Ranked topics", detail: `${count("P1")} P1 · ${count("P2")} P2 · ${count("P3")} P3` },
        { value: String(EDITION.covered), label: "Accounts posting", detail: `of ${EDITION.total} searched` },
        { value: String(EDITION.postsRead), label: "Posts read", detail: EDITION.window },
        { value: byTheme[0]?.label ?? "", label: "Loudest theme", detail: byTheme[0]?.display },
      ]} />
      <TableOfContents items={toc} />

      <Section heading="Headlines" id="headlines" caption="The P1 topics of this edition.">
        <Grid columns={3}>
          {p1.map((t: Topic) => (
            <Section key={t.id}>
              <Status tone="danger">{t.priority} · {t.theme}</Status>
              <Text><strong>{t.topic}</strong></Text>
              <AvatarStack people={people(t.voices)} max={5} label={`${t.count} watchlist voices`} />
              <LinkCards links={t.links.slice(0, 1)} />
            </Section>
          ))}
        </Grid>
      </Section>

      <Section heading="Priority map" id="map" caption="Breadth (distinct watchlist voices) against engagement (likes on the linked posts). Upper right ranks highest; priority also weighs impact and theme fit.">
        <Scatter
          points={TOPICS.map((t: Topic) => ({ x: t.count, y: t.likes, label: t.topic.split(":")[0], series: t.priority, size: t.likes }))}
          x={{ name: "Watchlist voices", floor: 0 }}
          y={{ name: "Likes on linked posts", floor: 0, format: fmtK }}
        />
        <Bars bars={byTheme} emphasis={0} />
      </Section>

      <Section heading="Ranked topics" id="ranked" caption="Filter by priority or theme.">
        <Grid plain columns={2}>
          <Segmented options={["All", "P1", "P2", "P3"].map((p: string) => ({ value: p, label: p, count: count(p) }))} value={prio} onChange={setPrio} />
          <Select label="Theme" options={themes} value={theme} onChange={setTheme} />
        </Grid>
        <Table columns={["Priority", "Topic", "Theme", "Voices", "Key names"]} align={["start", "start", "start", "end", "start"]} emphasis={1}
          rows={shown.map((t: Topic) => [<Status tone={PRIO_TONE[t.priority]}>{t.priority}</Status>, t.topic, t.theme, String(t.count), <AvatarStack people={people(t.voices)} max={4} size={24} />])} />
      </Section>

      <Section heading="Topic detail" id="detail">
        <Select label="Topic" options={TOPICS.map((t: Topic) => ({ value: t.id, label: `${t.priority} · ${t.topic}` }))} value={sel.id} onChange={setPick} />
        <Grid plain columns={2}>
          <Status tone={PRIO_TONE[sel.priority]}>{sel.priority} · {sel.theme}</Status>
          <AvatarStack people={people(sel.voices)} max={8} label={`${sel.count} voices`} />
        </Grid>
        <Text>{sel.summary}</Text>
        {sel.sides ? <ProsCons prosHeading="The case for" consHeading="Skeptics" pros={sel.sides[0]} cons={sel.sides[1]} /> : null}
        <Quote cite={sel.quote.cite}>{sel.quote.text}</Quote>
        <LinkCards links={sel.links} numbered />
      </Section>

      <Section heading="Reading and new voices" id="reading">
        <Grid columns={2}>
          <Section heading="Worth reading in full">
            <LinkCards links={[WORTH_READING]} />
          </Section>
          <Section heading="Suggested new voices">
            <Rows rows={NEW_VOICES.map((v) => ({ title: v.handle, detail: v.why }))} />
            <LinkCards links={NEW_VOICES.flatMap((v) => v.links)} />
          </Section>
        </Grid>
      </Section>

      <Section heading="Coverage" id="coverage">
        <Properties items={[
          { label: "Window", value: EDITION.window },
          { label: "Accounts searched", value: `${EDITION.total}, in batches of up to 15` },
          { label: "Accounts posting", value: `${EDITION.covered} of ${EDITION.total}` },
          { label: "Posts read", value: String(EDITION.postsRead) },
          { label: "Sourcing", value: "Original posts linked first; hype-leaning benchmark claims marked unconfirmed" },
        ]} />
      </Section>

      <Section heading="Edition history" id="history">
        <Table columns={["Edition", "Top line"]} rows={EDITIONS.map((e) => [e.date, e.topLine])} />
      </Section>
    </Page>
  );
}
```
